#root #barmodal .row button:not(:disabled):not(:hover):not(:focus){ background:transparent; color:#e6ff3d; border:1px solid #e6ff3d; }
/* v28.xx (cw-uc-rewbar2) b-31 step 7, critic on 13 (list stops 285px short of the card edge) and 16 (a 1060x185 list in a 1700 card, 20px names, 15px blurbs): rewards fill the card width; bar content 1400 wide with 120px rows, 72px icons, 28px names, 18px blurbs, 32px prices, 200x56 buttons. */
#root #opane_rew{ max-width:none !important; }
#root #barmodal .msub, #root #barmodal .plist{ max-width:1400px !important; width:100%; }
#root #barmodal .row{ min-height:120px; }
#root #barmodal .row img{ width:72px !important; height:72px !important; }
#root #barmodal .row b{ font-size:28px; }
#root #barmodal .row .hint{ font-size:18px; }
#root #barmodal .row .vl{ font-size:32px; font-family:var(--f-cond,inherit); font-weight:800; }
#root #barmodal .row button{ min-width:200px !important; min-height:56px; font-size:20px; }

check:
{v:'VER',what:'rewards list fills the card, bar rows scaled up (1400 wide, 120px rows, 56px buttons)',
 run:function(){
   var bad=[];
   try{
     var rw=document.getElementById('opane_rew');
     if(getComputedStyle(rw).maxWidth!=='none') bad.push('rew maxw '+getComputedStyle(rw).maxWidth);
     var pl=document.querySelector('#barmodal .plist');
     if(getComputedStyle(pl).maxWidth!=='1400px') bad.push('bar plist maxw '+getComputedStyle(pl).maxWidth);
     renderBar();
     var rowEl=document.querySelector('#barlist .row');
     if(!rowEl||parseFloat(getComputedStyle(rowEl).minHeight)<120) bad.push('bar row minh');
     var bt=document.querySelector('#barlist [data-bz]');
     if(!bt||parseFloat(getComputedStyle(bt).minHeight)<56) bad.push('bar button minh');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   return bad.length?bad.join('; '):null; }},
